/**
 * Level manifest generator (PERF-2). `src/levels/manifest.ts` is generated from `src/levels/*.json`
 * so the eager bundle only carries the per-level metadata (id, English name, star clocks) and one
 * dynamic `import()` per level; the level bodies become their own chunks. The translated names
 * (I18N-2) are a second generated file, `src/levels/names.ts`, imported only by the lazily loaded
 * level map (PERF-10: ≈ 1.8 kB gzip of Cyrillic / Turkic text out of the eager bundle). Shared by
 * `npm run levels:manifest` (writes both files) and `npm run levels:check` (fails when one is stale).
 */
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const LEVELS_DIR = fileURLToPath(new URL('../../src/levels/', import.meta.url));
export const MANIFEST_PATH = fileURLToPath(new URL('../../src/levels/manifest.ts', import.meta.url));
export const NAMES_PATH = fileURLToPath(new URL('../../src/levels/names.ts', import.meta.url));
export const LEVEL_FILE_RE = /^\d{3}-[a-z0-9-]+\.json$/;

/** Translated names ship in src/levels/names.ts (I18N-2, PERF-10); lessons stay in the level chunk. */
export const NAME_LANGS = ['az', 'ru', 'tr'] as const;
export type NameLang = (typeof NAME_LANGS)[number];

export interface ManifestEntry {
  file: string;
  id: number;
  name: string;
  /** `name_az` … present only when the JSON carries a non-empty translation. */
  names: Partial<Record<NameLang, string>>;
  star3: number;
  star2: number;
}

/** Level JSON files in play order (the numeric file prefix), as `NNN-name.json`. */
export function levelFiles(dir = LEVELS_DIR): string[] {
  return readdirSync(dir)
    .filter((f) => LEVEL_FILE_RE.test(f))
    .sort();
}

/** The metadata every manifest entry carries; validation of the rest is `validateLevel`'s job. */
export function readEntries(dir = LEVELS_DIR): ManifestEntry[] {
  return levelFiles(dir).map((file) => {
    const raw = JSON.parse(readFileSync(new URL(file, `file://${dir}`), 'utf8')) as Record<string, unknown>;
    const pick = (key: 'id' | 'star3' | 'star2'): number => {
      const v = raw[key];
      if (typeof v !== 'number' || !Number.isFinite(v)) throw new Error(`${file}: "${key}" must be a finite number`);
      return v;
    };
    const name = raw.name;
    if (typeof name !== 'string' || name.length === 0) throw new Error(`${file}: "name" must be a non-empty string`);
    const names: Partial<Record<NameLang, string>> = {};
    for (const lang of NAME_LANGS) {
      const v = raw[`name_${lang}`];
      if (v === undefined) continue;
      if (typeof v !== 'string' || v.trim() === '') throw new Error(`${file}: "name_${lang}" must be a non-empty string when present`);
      names[lang] = v;
    }
    return { file, id: pick('id'), name, names, star3: pick('star3'), star2: pick('star2') };
  });
}

const quote = (s: string): string => `'${s.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;

/** Source text of `src/levels/manifest.ts` for the given entries. */
export function renderManifest(entries: readonly ManifestEntry[]): string {
  const lines = entries.map(
    (e) => `  { id: ${e.id}, name: ${quote(e.name)}, star3: ${e.star3}, star2: ${e.star2}, load: () => import('./${e.file}').then(def) },`,
  );
  return [
    '/**',
    ' * GENERATED by `npm run levels:manifest` from src/levels/*.json — do not edit by hand.',
    ' * `npm run levels:check` fails while this file is stale (a level was added, renamed or its star',
    ' * clocks changed). Each `load` is a dynamic import so Vite emits one chunk per level (PERF-2);',
    ' * only the metadata below ships in the eager bundle (the translated names are ./names.ts, PERF-10).',
    ' * See src/levels/index.ts for the API.',
    ' */',
    "import type { LevelDef } from '../sim/types';",
    '',
    '/** JSON string fields are widened by TS; the validator (`npm run levels:check`) guards the enums. */',
    'const def = (m: { default: unknown }): LevelDef => m.default as LevelDef;',
    '',
    '/** Metadata per level (the English name; the translated ones are ./names.ts). */',
    'export interface LevelManifestEntry {',
    '  readonly id: number;',
    '  readonly name: string;',
    '  /** Star clocks in ms (GDD §3): finish under `star3` for three stars, under `star2` for two. */',
    '  readonly star3: number;',
    '  readonly star2: number;',
    '  readonly load: () => Promise<LevelDef>;',
    '}',
    '',
    '/** Every level in play order. */',
    'export const LEVEL_MANIFEST: readonly LevelManifestEntry[] = [',
    ...lines,
    '];',
    '',
  ].join('\n');
}

/** Source text of `src/levels/names.ts` (the translated level names, PERF-10) for the given entries. */
export function renderNames(entries: readonly ManifestEntry[]): string {
  const lines = entries.map((e) => {
    const names = NAME_LANGS.filter((lang) => e.names[lang] !== undefined)
      .map((lang) => `name_${lang}: ${quote(e.names[lang] as string)}`)
      .join(', ');
    return `  ${e.id}: { ${names} },`;
  });
  return [
    '/**',
    ' * GENERATED by `npm run levels:manifest` from src/levels/*.json — do not edit by hand.',
    ' * The translated level names (I18N-2), keyed by level id. Only the lazily loaded level map',
    ' * (src/ui/levelSelect.ts) draws names of levels that are not loaded, so they stay out of the eager',
    ' * bundle (PERF-10; tests/ui/tutorialChunk.test.ts); a loaded level carries its own `name_*`.',
    ' */',
    "import type { LevelTextTranslations } from '../ui/i18n';",
    '',
    "export type LevelNames = Pick<LevelTextTranslations, 'name_az' | 'name_ru' | 'name_tr'>;",
    '',
    '/** Translated names per level id. */',
    'export const LEVEL_NAMES: Readonly<Record<number, LevelNames>> = {',
    ...lines,
    '};',
    '',
  ].join('\n');
}

function staleness(label: string, path: string, expected: string): string[] {
  if (!existsSync(path)) return [`${path} is missing — run \`npm run levels:manifest\``];
  const actual = readFileSync(path, 'utf8');
  if (actual === expected) return [];
  const exp = expected.split('\n');
  const act = actual.split('\n');
  const at = exp.findIndex((line, i) => line !== act[i]);
  return [
    `${label} is stale (first difference at line ${at + 1}: expected ${JSON.stringify(exp[at] ?? '<eof>')}, ` +
      `found ${JSON.stringify(act[at] ?? '<eof>')}) — run \`npm run levels:manifest\``,
  ];
}

/** Errors that make the checked-in manifest or names file stale (empty = up to date). */
export function checkManifest(dir = LEVELS_DIR, path = MANIFEST_PATH, namesPath = NAMES_PATH): string[] {
  const entries = readEntries(dir);
  return [...staleness('src/levels/manifest.ts', path, renderManifest(entries)), ...staleness('src/levels/names.ts', namesPath, renderNames(entries))];
}
